set -eu
export PATH=/usr/sbin:/usr/bin:/sbin:/bin LC_ALL=C
# Every fact is a bounded single line. Missing prerequisites never certify absence.
fact() {
 key=$1; normalized=
 while :; do case "$key" in *-*) normalized="$normalized${key%%-*}_"; key="${key#*-}";; *) break;; esac; done
 value=$2
 case "$value" in *[!\ -~]*) value=not-assessed;; esac
 if test "${#value}" -gt 512; then value=not-assessed; fi
 printf 'FR_FACT %s=%s\n' "$normalized$key" "$value"
}
need() { for tool in "$@"; do if ! command -v "$tool" >/dev/null 2>&1; then fact probe_tools not-assessed; printf 'FR_NOTICE missing_tool=%s\n' "$tool" >&2; exit 0; fi; done; }
path_state() {
 if test -e "$1" || test -L "$1"; then printf present
 elif test -d "${1%/*}" && test -x "${1%/*}" && test -r "${1%/*}"; then printf missing
 else printf not-assessed; fi
}
# Capture is private, bounded to 128 KiB, and requires the producer's exit proof.
# Never export cap_output directly: callers select only fixed public fields/counts.
cap() {
 cap_output=
 command -v head >/dev/null 2>&1 && command -v tr >/dev/null 2>&1 || return 1
 cap_output=$({ "$@" 2>/dev/null; cap_code=$?; printf '\nFR_CAPTURE_EXIT=%s\n' "$cap_code"; } | head -c 131073 | tr '\000' '?'; printf '.')
 cap_output=${cap_output%.}
 test "${#cap_output}" -lt 131073 || { cap_output=; return 1; }
 case "$cap_output" in *'
FR_CAPTURE_EXIT=0
') cap_output=${cap_output%'
FR_CAPTURE_EXIT=0
'}; return 0;; *) cap_output=; return 1;; esac
}
if ! command -v awk >/dev/null 2>&1; then fact kernel_config_source not-assessed;exit 0;fi
filter_config() { awk '
BEGIN{split("CONFIG_NETFILTER CONFIG_TUN CONFIG_NAMESPACES CONFIG_USER_NS CONFIG_NET_NS CONFIG_CGROUPS CONFIG_SECCOMP CONFIG_SECURITY_SELINUX CONFIG_USB_CONFIGFS CONFIG_OVERLAY_FS CONFIG_EXT4_FS CONFIG_QRTR CONFIG_QCOM_Q6V5_PAS CONFIG_DEVMEM CONFIG_PROC_KCORE",a," ");for(i in a)w[a[i]]=1}
/^CONFIG_[A-Z0-9_]+=[ymn]$/ {split($0,x,"=");if(x[1] in w){seen[x[1]]=1;print "FR_FACT kernel_" tolower(x[1]) "=" x[2]}}
/^# CONFIG_[A-Z0-9_]+ is not set$/ {if($2 in w){seen[$2]=1;print "FR_FACT kernel_" tolower($2) "=n"}}
END{for(k in w)if(!(k in seen))print "FR_FACT kernel_" tolower(k) "=not-assessed"}' ; }
if test -r /proc/config.gz && cap gzip -cd /proc/config.gz; then printf '%s\n' "$cap_output" | filter_config;fact kernel_config_source proc_config
else fact kernel_config_source not-assessed;fi
for item in cgroup:/sys/fs/cgroup namespaces:/proc/self/ns selinux:/sys/fs/selinux;do name=${item%%:*};path=${item#*:};fact "kernel_runtime_$name" "$(path_state "$path")";done

