state() {
 s_path=$1; s_parent=${s_path%/*}
 while test -n "$s_parent"; do
  if test -L "$s_parent" || test ! -d "$s_parent" || test ! -r "$s_parent" || test ! -x "$s_parent"; then printf not-assessed; return; fi
  test "$s_parent" != / || break
  s_parent=${s_parent%/*}; test -n "$s_parent" || s_parent=/
 done
 if test -L "$s_path"; then printf symlink
 elif test -e "$s_path"; then printf present
 else printf missing; fi
}
one() {
 case "$cap_output" in *'
') cap_output=${cap_output%'
'};; esac
 case "$cap_output" in *'
'*) return 1;; esac
}
valid_hash() { case "$1" in ''|*[!0-9a-f]*) return 1;; esac; test "${#1}" = 64; }
plain() { test "$(state "$1")" = present && test -f "$1" && test -r "$1"; }
hash_file() {
 h_key=$1; h_path=$2; h_state=$(state "$h_path")
 if test "$h_state" != present; then fact "$h_key" "$h_state"; return; fi
 if ! plain "$h_path" || ! command -v stat >/dev/null 2>&1 || ! command -v sha256sum >/dev/null 2>&1; then fact "$h_key" not-assessed; return; fi
 h_size=$(stat -c %s "$h_path" 2>/dev/null) || h_size=invalid
 case "$h_size" in ''|*[!0-9]*) fact "$h_key" not-assessed; return;; esac
 if test "$h_size" -gt 67108864 || ! cap sha256sum "$h_path"; then fact "$h_key" not-assessed; return; fi
 h_value=${cap_output%% *}
 case "$h_value" in ''|*[!0-9a-f]*) h_value=not-assessed;; *) test "${#h_value}" = 64 || h_value=not-assessed;; esac
 fact "$h_key" "$h_value"
}
bool_match() {
 b_key=$1; b_path=$2; b_expected=$3
 if plain "$b_path" && cap cat "$b_path" && one; then
  if test "$cap_output" = "$b_expected"; then fact "$b_key" 1; else fact "$b_key" 0; fi
 else fact "$b_key" not-assessed; fi
}

