ose wanapn zte_end zte_start",a," ");for(i in a)args[a[i]]=1}
   $1==sprintf("%c%s%c",39,obj,39)&&$2~/^@[0-9a-fA-F]+$/&&NF==2{header++;next}
   /^[ \t]*"[A-Za-z0-9_]+"[ \t]*:/ {
    line=$0;sub(/^[ \t]*"/,"",line);method=line;sub(/".*$/,"",method);if(!(method in allowed))next;
    if(seen[method]++){bad=1;next};count++; printf "RPC_METHOD %s.%s\n",obj,method;
    sub(/^[^"]*"[ \t]*:[ \t]*/,"",line);sub(/[ \t]*,[ \t]*$/,"",line);
